INSERT INTO consultation_reports (id, appointment_id, patient_id, patient_name, patient_age, patient_gender, doctor_id, doctor_name, doctor_specialty, hospital, location, date, time, chief_complaint, symptoms_reported, patient_provided_info, doctor_observations, doctor_notes, clinical_summary, advice, follow_up, status, created_at) VALUES ('rep-101', 'apt-past-1', 'pat-1', 'Rahul Sharma', 31, 'Male', 'doc-1', 'Dr. Priya Sharma', 'Cardiologist', 'Apollo Heart & Vascular Institute, Greams Road', 'Chennai', '2026-09-20', '02:30 PM', 'Quarterly hypertension review and resting ECG evaluation', 'Occasional mild morning headache, no chest pain, no palpitations', 'Compliant with Telmisartan 40mg. Home BP logs average 128/84 mmHg.', 'Blood pressure 126/82 mmHg. Pulse 72 bpm, regular. Heart sounds S1 S2 normal, no murmurs. Lungs clear to auscultation bilaterally.', 'Cardiovascular examination within target therapeutic limits. Good lifestyle adherence.', 'Stage 1 Essential Hypertension (Well Controlled). Resting 12-lead ECG demonstrates normal sinus rhythm with no ischemic changes.', '1. Continue Tab Telmisartan 40mg once daily after breakfast.
INSERT INTO consultation_reports (id, appointment_id, patient_id, patient_name, patient_age, patient_gender, doctor_id, doctor_name, doctor_specialty, hospital, location, date, time, chief_complaint, symptoms_reported, patient_provided_info, doctor_observations, doctor_notes, clinical_summary, advice, follow_up, status, created_at) VALUES ('rep-102', 'apt-past-2', 'pat-1', 'Rahul Sharma', 31, 'Male', 'doc-20', 'Dr. Arjun Kumar', 'Dermatologist', 'Skin & Aesthetic Laser Centre, Indiranagar', 'Bangalore', '2026-08-15', '11:00 AM', 'Contact dermatitis and itching on forearms after garden work', 'Erythematous papules, localized pruritus for 4 days', 'No prior drug allergies reported. Used over-the-counter moisturizer without relief.', 'Multiple discrete erythematous papules on bilateral extensor forearm surfaces. No secondary infection.', 'Classic allergic contact dermatitis presentation. Advised protective clothing.', 'Acute Contact Dermatitis (Resolved with topical corticosteroids).', '1. Apply Mometasone Furoate 0.1% cream sparingly twice daily for 5 days.
